from xml.etree import ElementTree as ET

p = r"E:\TTQS\_github_sync_0064\docs\ttqs-quality-20261016\quality-review\0067_R01\candidate\0067_R03.docx"
z = zipfile.ZipFile(p)
W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"

def text_of(elem):
    return "".join(t.text or "" for t in elem.iter(W+"t"))

doc = ET.fromstring(z.read("word/document.xml"))
body = doc.find(W+"body")
out = []
n = 0
for child in body:
    tag = child.tag.replace(W, "")
    if tag == "p":
        txt = text_of(child)
        style = ""
        pPr = child.find(W+"pPr")
        if pPr is not None:
            st = pPr.find(W+"pStyle")
            if st is not None:
                style = st.get(W+"val", "")
        out.append(f"[P:{style}] {txt}")
    elif tag == "tbl":
        out.append("[TABLE]")
        for row in child.findall(W+"tr"):
            cells = []
            for tc in row.findall(W+"tc"):
                cells.append(text_of(tc).replace("\n", " "))
            out.append(" | ".join(cells))
        out.append("[/TABLE]")
    else:
        out.append(f"[{tag}]")

with open(r"C:\Users\J\AppData\Local\Temp\opencode\docx_extracted.txt", "w", encoding="utf-8") as f:
    f.write("\n".join(out))
print("paragraphs/tables written:", len(out))
PY"}

